.latest-receipt {
  position: relative;
  margin-top: 20px;
  padding: 18px 17px 14px;
  overflow: hidden;
  border-radius: 3px;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.4), transparent 35%),
    var(--paper);
  color: var(--paper-ink);
  box-shadow: 0 14px 32px rgba(0, 0, 0, 0.2);
  animation: receipt-change 500ms ease both;

.thought-node[data-kind="question"] {
  color: var(--teal);
}

.thought-node[data-kind="constraint"] {
  color: var(--amber);
}

.thought-node[data-kind="refusal"] {
  color: var(--coral);
}

.thought-node[data-kind="memory"] {
  color: var(--lilac);
}

function handleKindKeys(event) {
  if (!["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown"].includes(event.key)) {
    return;
  }
  event.preventDefault();
  const kinds = Object.keys(KIND_CONFIG);
  const direction = event.key === "ArrowRight" || event.key === "ArrowDown" ? 1 : -1;
  const currentIndex = kinds.indexOf(selectedKind);
  const nextIndex = (currentIndex + direction + kinds.length) % kinds.length;
  selectKind(kinds[nextIndex], true);
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
}

.gesture-panel__heading p {
  display: none;
}

.kind {
  justify-content: center;
}

.kind > span:last-child {
  display: none;
}
